    const float* A,
    const float* B,
    float* C,
    int N) {

    // Shared memory for tiles
    __shared__ float As[16][16];
    __shared__ float Bs[16][16];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * blockDim.y + ty;
    int col = blockIdx.x * blockDim.x + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + 15) / 16; t++) {
        // Load tile of A
        int A_col = t * 16 + tx;
        if (row < N && A_col < N) {
