    const float* A,
    const float* B,
    float* C,
    int N) {

    // Shared memory for tiles with double buffering
    __shared__ float As[2][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[2][TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE_SIZE + ty * 4;
    int col = blockIdx.x * TILE_SIZE + tx * 4;

    float c[4][4] = {{0}};

    // Prefetch first tile
    if (row < N && tx*4 < TILE_SIZE) {
        for (int i = 0; i < 4; i++) {
            int r = row + i;
            if (r < N) {
                for (int j = 0; j < 4; j++) {
                    int c_idx = tx*4 + j;
                    if (c_idx < TILE_SIZE) {
                        As[0][ty*4+i][tx*4+j] = A[r * N + c_idx];
                    }
                }
            }
        }
    }

    if (col < N && ty*4 < TILE_SIZE) {
        for (int i = 0; i < 4; i++) {
            int r = ty*4 + i;
            if (r < TILE_SIZE) {
                for (int j = 0; j < 4; j++) {
                    int c_idx = col + j;
                    if (c_idx < N) {
                        Bs[0][ty*4+i][tx*4+j] = B[r * N + c_idx];
                    }
                }
            }
        }
    }

    __syncthreads();

