    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        int next_buffer = 1 - buffer;

        // Prefetch next tile
        if (t + 1 < (N + TILE_SIZE - 1) / TILE_SIZE) {
            int next_tile = t + 1;
            int A_col = next_tile * TILE_SIZE + tx * 4;
            if (row < N && A_col < N) {
